//! W11 golden-fixture harness: CP pdf/quantiles for the four Phase-1 models not
//! covered by `cp_golden.rs` — `genextreme`, `genextreme_p1`, `genpareto`,
//! `norm_p1` — vs. the reference `fitdistcp` R package.
//!
//! Loads `tests/golden/w11_cp_golden.json` (generated by
//! `tools/generate_w11_cp_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and compares the Rust DMGS CP predictive density
//! and quantiles against the reference values.
//!
//! # Tolerance policy (§7.2)
//!
//! The consolidated, canonical tolerance policy lives in
//! [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md); the summary
//! below is the subset relevant to this harness.
//!
//! - **genpareto**: the Rust GPD uses the reference's **analytic** derivatives
//!   (`gpd_k1_*`), so the two agree to near machine precision. Observed max
//!   relative residuals: CP pdf `2.9e-7`, CP quantiles `2.1e-7`. Compared with
//!   `GPD_RTOL = 1e-6` (the §7.2 quantile-derived-density tolerance).
//! - **genextreme** (negative and positive shape): the Rust GEV keeps the
//!   **numerical** third-derivative fallback (the reference's `gev_logfddd` is a
//!   ~180-line machine-generated expression), so the DMGS bias-correction term
//!   carries finite-difference error. Observed max relative residuals: negative
//!   shape CP pdf `2.4e-5` / CP quantiles `1.6e-4`; positive shape CP pdf
//!   `8.5e-6` / CP quantiles `4.0e-6`. Compared with `GEV_RTOL = 1e-3` (a ~6×
//!   margin over the worst case, still catching any formula/sign bug). This is
//!   the same documented difference as `gev_negshape_golden.rs`.
//! - **genextreme_p1**: same numerical-third-derivative caveat; observed CP
//!   quantile residual `~5e-6`. Compared with `GEV_RTOL = 1e-3`.
//! - **norm_p1**: the reference `qnorm_p1_cp` returns the **analytic** CP
//!   (`qnorm_p1_formula`, a t-distribution formula), not the DMGS expansion.
//!   The Rust port implements the DMGS expansion, so the apples-to-apples
//!   comparison is against the reference's own DMGS CP (`cp_quantiles_dmgs`),
//!   evaluated at the **same parameters**. Observed residual `4.8e-7`, compared
//!   with `NORMP1_DMGS_RTOL = 1e-6`. The analytic CP is also compared, with the
//!   documented `O(1/n)` DMGS truncation tolerance `NORMP1_TRUNC_RTOL = 5e-2`.
//!
//! # Documented legitimate differences
//!
//! - **norm_p1 MLE sigma convention**: the reference `norm_p1_mlparams` uses the
//!   **unbiased** residual SD (`sd(lm$residuals)`, n-1 denominator), whereas the
//!   Rust `fit` converges to the **true MLE** (biased, n denominator). This is
//!   the same documented quirk as `mle_golden.json`. The harness therefore
//!   compares the Rust DMGS against the reference DMGS at the **same params**
//!   (isolating the expansion), and separately checks that the Rust MLE matches
//!   the reference params up to the `sqrt((n-1)/n)` sigma factor.
//! - **`_p1` prediction point (W14)**: the Rust `_p1` models center the
//!   predictor by its mean (`t_i - mean(t)`) and evaluate the DMGS expansion at
//!   the prediction point `t0 - mean(t)`. The fixture emits the reference CP at
//!   the prediction point `t0 = t[0]` in the mean-centered predictor space, and
//!   the harness passes that `t0` to the model, so the two coincide.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::dmgs::DmgsIntegrator;
use fitdistcp_core::mle::fit;
use fitdistcp_core::models::{GenExtreme, GenExtremeP1, GenPareto, NormalP1};

/// Tolerance for the GPD CP (analytic derivatives; observed max `2.9e-7`).
const GPD_RTOL: f64 = 1e-6;
const GPD_ATOL: f64 = 1e-10;

/// Tolerance for the GEV / GEV-p1 CP (numerical third-derivative fallback;
/// observed max `1.6e-4`).
const GEV_RTOL: f64 = 1e-3;
const GEV_ATOL: f64 = 1e-10;

/// Tolerance for the norm_p1 DMGS CP vs. the reference DMGS CP at the same
/// params (observed max `4.8e-7`).
const NORMP1_DMGS_RTOL: f64 = 1e-6;
const NORMP1_DMGS_ATOL: f64 = 1e-10;

/// Tolerance for the norm_p1 DMGS CP vs. the reference **analytic** CP. The
/// DMGS expansion is a first-order approximation of the exact integral, so the
/// two differ by the `O(1/n)` truncation error (observed ~2.4%).
const NORMP1_TRUNC_RTOL: f64 = 5e-2;
const NORMP1_TRUNC_ATOL: f64 = 1e-4;

/// The reference `fdalpha` default for the quantile-derived density.
const FDALPHA: f64 = 0.01;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.bytes[self.pos + 1..self.pos + 5])
                                .expect("utf8 hex");
                            let code = u32::from_str_radix(hex, 16).expect("hex");
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            self.pos += 4;
                        }
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "w11_cp_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

/// The reference `fdalpha`-based quantile-derived CP density, computed from the
/// Rust CP quantile function (mirrors `DmgsIntegrator::cp_pdf_quantile_derived`).
fn cp_pdf_quantile_derived<M: fitdistcp_core::dmgs::DmgsModel + Sync>(
    integ: &DmgsIntegrator<M>,
    params: &[f64],
    y: &[f64],
    p_grid: &[f64],
) -> Vec<f64> {
    let alpha: Vec<f64> = p_grid.iter().map(|&p| 1.0 - p).collect();
    integ.cp_pdf_quantile_derived(params, y, &alpha, FDALPHA)
}

#[test]
fn golden_w11_genextreme_negative_shape() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get("gev_neg").as_f64_vec();
    let m = models.get("genextreme");
    let ref_params = m.get("params").as_f64_vec();

    let r = fit(&GenExtreme, &y, &[0.0, 1.0, -0.1]);
    assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "gev.loc");
    assert_close(r.ml_params[1], ref_params[1], 1e-4, 1e-6, "gev.scale");
    assert_close(r.ml_params[2], ref_params[2], 1e-4, 1e-6, "gev.shape");
    assert!(r.ml_params[2] < 0.0, "expected negative shape");

    let integ = DmgsIntegrator::new(GenExtreme);
    let cp_q = integ.cp_quantiles(&r.ml_params, &y, &p_grid);
    compare_vec(
        &cp_q,
        &m.get("cp_quantiles").as_f64_vec(),
        GEV_RTOL,
        GEV_ATOL,
        "genextreme.cp_quantiles",
    );
    let cp_pdf = cp_pdf_quantile_derived(&integ, &r.ml_params, &y, &p_grid);
    compare_vec(
        &cp_pdf,
        &m.get("cp_pdf").as_f64_vec(),
        GEV_RTOL,
        GEV_ATOL,
        "genextreme.cp_pdf",
    );
}

#[test]
fn golden_w11_genextreme_positive_shape() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get("gev_pos").as_f64_vec();
    let m = models.get("genextreme_pos");
    let ref_params = m.get("params").as_f64_vec();

    let r = fit(&GenExtreme, &y, &[1.0, 1.0, 0.1]);
    assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "gevpos.loc");
    assert_close(r.ml_params[1], ref_params[1], 1e-4, 1e-6, "gevpos.scale");
    assert_close(r.ml_params[2], ref_params[2], 1e-4, 1e-6, "gevpos.shape");
    assert!(r.ml_params[2] > 0.0, "expected positive shape");

    let integ = DmgsIntegrator::new(GenExtreme);
    let cp_q = integ.cp_quantiles(&r.ml_params, &y, &p_grid);
    compare_vec(
        &cp_q,
        &m.get("cp_quantiles").as_f64_vec(),
        GEV_RTOL,
        GEV_ATOL,
        "genextreme_pos.cp_quantiles",
    );
    let cp_pdf = cp_pdf_quantile_derived(&integ, &r.ml_params, &y, &p_grid);
    compare_vec(
        &cp_pdf,
        &m.get("cp_pdf").as_f64_vec(),
        GEV_RTOL,
        GEV_ATOL,
        "genextreme_pos.cp_pdf",
    );
}

#[test]
fn golden_w11_genpareto() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get("gpd").as_f64_vec();
    let m = models.get("genpareto");
    let ref_params = m.get("params").as_f64_vec();

    let r = fit(&GenPareto, &y, &[1.0, -0.1]);
    assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "gpd.scale");
    assert_close(r.ml_params[1], ref_params[1], 1e-4, 1e-6, "gpd.shape");

    let integ = DmgsIntegrator::new(GenPareto);
    let cp_q = integ.cp_quantiles(&r.ml_params, &y, &p_grid);
    compare_vec(
        &cp_q,
        &m.get("cp_quantiles").as_f64_vec(),
        GPD_RTOL,
        GPD_ATOL,
        "genpareto.cp_quantiles",
    );
    let cp_pdf = cp_pdf_quantile_derived(&integ, &r.ml_params, &y, &p_grid);
    compare_vec(
        &cp_pdf,
        &m.get("cp_pdf").as_f64_vec(),
        GPD_RTOL,
        GPD_ATOL,
        "genpareto.cp_pdf",
    );
}

#[test]
fn golden_w11_norm_p1() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let x = datasets.get("norm_p1_x").as_f64_vec();
    let t = datasets.get("norm_p1_t").as_f64_vec();
    let m = models.get("norm_p1");
    let ref_params = m.get("params").as_f64_vec();
    let rust_params = m.get("rust_params").as_f64_vec();

    // W14: the Rust model centers the predictor by its mean, `t_i - mean(t)`.
    // The fixture's `t` is already mean-centered (mean ~ 0), so the fit matches
    // the reference. The fixture predicts at `t0 = t[0]` (centered space), so we
    // pass that as the prediction point.
    let t0 = t[0];
    let model = NormalP1::new(t.clone(), t0, 1.0);
    let r = fit(&model, &x, &[0.0, 1.0, 1.0]);

    // The Rust MLE matches the reference params up to the documented sigma
    // convention: the reference uses the UNBIASED sd (n-1), Rust the true MLE.
    let n = x.len() as f64;
    let sigma_mle = ref_params[2] * ((n - 1.0) / n).sqrt();
    assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "norm_p1.beta0");
    assert_close(r.ml_params[1], ref_params[1], 1e-4, 1e-6, "norm_p1.beta1");
    assert_close(r.ml_params[2], sigma_mle, 1e-4, 1e-6, "norm_p1.sigma_mle");

    let integ = DmgsIntegrator::new(model);

    // (a) Apples-to-apples: Rust DMGS vs. the reference DMGS at the SAME params.
    let cp_q_same = integ.cp_quantiles(&rust_params, &x, &p_grid);
    compare_vec(
        &cp_q_same,
        &m.get("cp_quantiles_dmgs_rustparams").as_f64_vec(),
        NORMP1_DMGS_RTOL,
        NORMP1_DMGS_ATOL,
        "norm_p1.cp_quantiles_dmgs_rustparams",
    );

    // (b) Rust DMGS at the Rust MLE params vs. the reference DMGS at the
    // reference params (the two differ only by the sigma convention).
    let cp_q = integ.cp_quantiles(&r.ml_params, &x, &p_grid);
    compare_vec(
        &cp_q,
        &m.get("cp_quantiles_dmgs").as_f64_vec(),
        NORMP1_TRUNC_RTOL,
        NORMP1_TRUNC_ATOL,
        "norm_p1.cp_quantiles_dmgs",
    );

    // (c) Cross-check: Rust DMGS vs. the reference ANALYTIC CP (looser,
    // documented O(1/n) truncation).
    compare_vec(
        &cp_q,
        &m.get("cp_quantiles_analytic").as_f64_vec(),
        NORMP1_TRUNC_RTOL,
        NORMP1_TRUNC_ATOL,
        "norm_p1.cp_quantiles_analytic",
    );
}

#[test]
fn golden_w11_genextreme_p1() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let x = datasets.get("gev_p1_x").as_f64_vec();
    let t = datasets.get("gev_p1_t").as_f64_vec();
    let m = models.get("genextreme_p1");
    let ref_params = m.get("params").as_f64_vec();

    // W14: the model centers by mean(t); the fixture's `t` is mean-centered and
    // predicts at `t0 = t[0]` (centered space).
    let t0 = t[0];
    let model = GenExtremeP1::new(t.clone(), t0, 1.0);
    let r = fit(&model, &x, &[0.0, 1.0, 1.0, -0.1]);

    assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "gev_p1.beta0");
    assert_close(r.ml_params[1], ref_params[1], 1e-4, 1e-6, "gev_p1.beta1");
    assert_close(r.ml_params[2], ref_params[2], 1e-4, 1e-6, "gev_p1.scale");
    assert_close(r.ml_params[3], ref_params[3], 1e-4, 1e-6, "gev_p1.shape");

    let integ = DmgsIntegrator::new(model);
    let cp_q = integ.cp_quantiles(&r.ml_params, &x, &p_grid);
    compare_vec(
        &cp_q,
        &m.get("cp_quantiles").as_f64_vec(),
        GEV_RTOL,
        GEV_ATOL,
        "genextreme_p1.cp_quantiles",
    );
}
